param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'decimal-generic-integer-native-conversion-bridge-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$definition=@([decimal].GetMethods([Reflection.BindingFlags]'Public,Static')|Where-Object {$_.Name -eq 'ConvertToIntegerNative' -and $_.IsGenericMethodDefinition});if($definition.Count -ne 1){throw 'One generic ConvertToIntegerNative definition required'};$rows=[Collections.Generic.List[object]]::new()
foreach($target in $plan.targets){$native=[type]::GetType($target,$true);$closed=$definition[0].MakeGenericMethod([type[]]@($native));for($index=0;$index -lt $plan.bits.Count;$index++){$value=[decimal]::new([int[]]$plan.bits[$index]);$actual=$closed.Invoke($null,[object[]]@($value));if($actual.GetType() -ne $native){throw 'Generic result type mismatch'};$text=if($target -eq 'System.Char'){([int]$actual).ToString([Globalization.CultureInfo]::InvariantCulture)}else{$actual.ToString([Globalization.CultureInfo]::InvariantCulture)};$rows.Add([ordered]@{target=$target;index=$index;value=$text;resultType=$actual.GetType().FullName;afterBits=[decimal]::GetBits($value)})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS Decimal ConvertToIntegerNative: $($rows.Count) native calls"
